        "html": "<uii-wizard>\n  <uii-form-wizard-step [title]=\"'Step 1'\">\n    <div>This is step 1</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 2'\">\n    <div>This is step 2</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 3'\">\n    <div>This is step 3</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 4'\">\n    <div>This is step 4</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 5'\">\n    <div>This is step 5</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 6'\">\n    <div>This is step 6</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 7'\">\n    <div>This is step 7</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 8'\">\n    <div>This is step 8</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 9'\">\n    <div>This is step 9</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 10'\">\n    <div>This is step 10</div>\n  </uii-form-wizard-step>\n</uii-wizard>",
