        "component": "ActiveStepOptionFormWizardComponent",
        "html": "<uii-wizard [activeStepCurrent]=\"2\" [activeStepStart]=\"1\" [activeStepEnd]=\"3\">\n  <uii-form-wizard-step [title]=\"'Step 1'\">\n    <div>This is step 1</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 2'\">\n    <div>This is step 2</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 3'\">\n    <div>This is step 3</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 4'\">\n    <div>This is step 4</div>\n  </uii-form-wizard-step>\n  <uii-form-wizard-step [title]=\"'Step 5'\">\n    <div>This is step 5</div>\n  </uii-form-wizard-step>\n</uii-wizard>\nActive step current: {{ activeStepCurrent }}<br>\nActive step start: {{ activeStepStart }}<br>\nActive step end: {{ activeStepEnd }}<br>",
        "ts": "import { Component, OnInit } from '@angular/core';\n\n@Component({\n  selector: 'ugw-active-step-option-form-wizard',\n  templateUrl: './active-step-option-form-wizard.component.html'\n})\nexport class ActiveStepOptionFormWizardComponent implements OnInit {\n\n  activeStepCurrent = 2;\n  activeStepStart = 1;\n  activeStepEnd = 3;\n  constructor() { }\n\n  ngOnInit() {\n  }\n\n}",
