        "html": "<div class=\"row\">\n  <div class=\"col-sm-12 col-md-3\"><uii-info-box title=\"Success\" subtitle=\"100%\" type=\"success\" infoIcon=\"fa fa-bar-chart\"></uii-info-box></div>\n  <div class=\"col-sm-12 col-md-3\"><uii-info-box title=\"Info\" subtitle=\"Yes\" type=\"info\" infoIcon=\"fa fa-check\"></uii-info-box></div>\n  <div class=\"col-sm-12 col-md-3\"><uii-info-box title=\"Danger\" subtitle=\"85.0\" type=\"danger\" infoIcon=\"fa fa-area-chart\"></uii-info-box></div>\n  <div class=\"col-sm-12 col-md-3\"><uii-info-box title=\"Warning\" subtitle=\"20\" type=\"warning\" infoIcon=\"fa fa-exclamation-triangle\"></uii-info-box></div>\n</div>",
