        "ts": "import { Component, OnInit } from '@angular/core';\n\n@Component({\n  selector: 'ugw-information-with-tag-html',\n  templateUrl: './information-with-tag-html.component.html',\n  styleUrls: ['./information-with-tag-html.component.scss']\n})\nexport class InformationWithTagHtmlComponent implements OnInit {\n\n  message_success = '<div class=\\\"information-title\\\"><h4>This is success</h4><p>This is the success text using the html tag</p></div>';\n  message_warning = '<div class=\\\"information-title\\\"><h4>This is warning</h4><p>This is the warning text using the html tag</p></div>';\n  message_error = '<div class=\\\"information-title\\\"><h4>This is error</h4><p>This is the error text using the html tag</p></div>';\n  message_info = '<div class=\\\"information-title\\\"><h4>This is info</h4><p>This is the info text using the html tag</p></div>';\n\n  constructor() { }\n\n  ngOnInit() {\n  }\n\n}",
