        "component": "ConfirmDialog2CustomComponent",
        "html": "<div class=\"row\">\n  <div class=\"col-md-3 margin-bottom-20\">\n    <button class=\"btn btn-primary\" (click)=\"displaySuccessDialog()\">\n      Show Success Dialog 2\n    </button>\n  </div>\n  <div class=\"col-md-3 margin-bottom-20\">\n    <button class=\"btn btn-primary\" (click)=\"displayConfirmDialog()\">\n      Show Confirm Dialog 2\n    </button>\n  </div>\n  <div class=\"col-md-3 margin-bottom-20\">\n    <button class=\"btn btn-primary\" (click)=\"displayConfirmDialog()\">\n      Confirm Dialog 2 Custom\n    </button>\n  </div>\n  <div class=\"col-md-3 margin-bottom-20\">\n    <button class=\"btn btn-primary\" (click)=\"displayWarningDialog()\">\n      Show Warning Dialog 2\n    </button>\n  </div>\n  <div class=\"col-md-3 margin-bottom-20\">\n    <button class=\"btn btn-primary\" (click)=\"displayDangerDialog()\">\n      Show Danger Dialog 2\n    </button>\n  </div>\n</div>",
