        "ts": "import { Component } from '@angular/core';\n\n@Component({\n  selector: 'ugw-set-page',\n  templateUrl: './set-page.component.html'\n})\nexport class SetPageComponent {\n\n  currentPage: number;\n\n  onPageChange(page: number) {\n    this.currentPage = page;\n  }\n\n}",
