        "ts": "import { Component, OnInit } from '@angular/core';\n\n@Component({\n  selector: 'ugw-table-with-custom-action',\n  templateUrl: './table-with-custom-action.component.html',\n  styleUrls: ['./table-with-custom-action.component.scss']\n})\nexport class TableWithCustomActionComponent implements OnInit {\n\n  rows: Array<any> = [];\n  columns: Array<any> = [];\n  actionSelected: string;\n  rowSelected: string;\n\n  constructor() { }\n\n  ngOnInit() {\n    this.columns = [\n      {\n        name: 'No',\n        prop: 'number'\n      },\n      {\n        name: 'Name',\n        prop: 'name'\n      },\n      {\n        name: 'Age',\n        prop: 'age'\n      },\n    ];\n\n    this.rows = [\n      {\n        name: 'Marta Mccoy',\n        age: 31,\n        additional_action: [\n          {\n            icon_class: 'fa fa-file',\n            tooltip: 'File',\n            click: (row) => {\n              this.actionSelected = 'file';\n              this.rowSelected = row;\n            }\n          },\n          {\n            icon_class: 'fa fa-folder',\n            tooltip: 'Archive',\n            click: (row) => {\n              this.actionSelected = 'archive';\n              this.rowSelected = row;\n            }\n          },\n        ]\n      },\n      {\n        name: 'Fanny Holman',\n        age: 23,\n        additional_action: [\n          {\n            icon_class: 'fa fa-folder',\n            tooltip: 'Archive',\n            click: (row) => {\n              this.actionSelected = 'archive';\n              this.rowSelected = row;\n            }\n          },\n        ]\n      },\n    ];\n  }\n\n}",
