        "ts": "import { Component, OnInit } from '@angular/core';\n\n@Component({\n  selector: 'ugw-table-with-checkbox',\n  templateUrl: './table-with-checkbox.component.html',\n  styleUrls: ['./table-with-checkbox.component.scss']\n})\nexport class TableWithCheckboxComponent implements OnInit {\n\n  rows: Array<any> = [];\n  columns: Array<any> = [];\n  rowSelected: Array<any> = [];\n\n  constructor() { }\n\n  ngOnInit() {\n    this.columns = [\n      {\n        name: 'No',\n        prop: 'number'\n      },\n      {\n        name: 'Name',\n        prop: 'name'\n      },\n      {\n        name: 'Age',\n        prop: 'age'\n      },\n    ];\n\n    this.rows = [\n      {\n        name: 'Marta Mccoy',\n        age: 31,\n        has_checkbox: false\n      },\n      {\n        name: 'Fanny Holman',\n        age: 23\n      },\n      {\n        name: 'Latonya Gibson',\n        age: 22,\n        has_checkbox: false\n      },\n      {\n        name: 'Ines Wiggins',\n        age: 35,\n        has_checkbox_checked_default: true,\n      },\n      {\n        name: 'Kathrine Irwin',\n        age: 38\n      },\n      {\n        name: 'Higgins Oneal',\n        age: 35,\n        has_checkbox_checked_default: true,\n      },\n      {\n        name: 'Russell Duke',\n        age: 37\n      },\n      {\n        name: 'Sara Quinn',\n        age: 23\n      },\n      {\n        name: 'Dona Patterson',\n        age: 32\n      },\n      {\n        name: 'Clarice Keith',\n        age: 22\n      },\n      {\n        name: 'Petersen Maldonado',\n        age: 20\n      },\n      {\n        name: 'Tonya Colon',\n        age: 38\n      },\n      {\n        name: 'Ann Bass',\n        age: 30\n      },\n      {\n        name: 'Cherie Pickett',\n        age: 21\n      },\n      {\n        name: 'Holland Mcdonald',\n        age: 28\n      },\n      {\n        name: 'Casey Dudley',\n        age: 23\n      },\n      {\n        name: 'Sophie Slater',\n        age: 33\n      },\n      {\n        name: 'Rhoda Kent',\n        age: 32\n      },\n      {\n        name: 'Bennett Sheppard',\n        age: 32\n      },\n      {\n        name: 'Foreman Hood',\n        age: 25\n      }\n    ];\n  }\n\n  onRowSelected($event) {\n    this.rowSelected = $event;\n  }\n\n}",
