        "ts": "import { Component, OnInit } from '@angular/core';\n\n@Component({\n  selector: 'ugw-summary-row-table',\n  templateUrl: './summary-row-table.component.html',\n  styleUrls: ['./summary-row-table.component.scss']\n})\nexport class SummaryRowTableComponent implements OnInit {\n\n  rows: Array<any> = [];\n  summaryRows = {\n    salary: 0,\n    gender: ''\n  };\n  columns: Array<any> = [];\n  selectedRow: any;\n\n  constructor() { }\n\n  ngOnInit() {\n    this.columns = [\n      {\n        name: 'No',\n        prop: 'number'\n      },\n      {\n        name: 'Name',\n        prop: 'name'\n      },\n      {\n        name: 'Salary',\n        prop: 'salary',\n        type: 'number'\n      },\n      {\n        name: 'Gender',\n        prop: 'gender'\n      },\n    ];\n\n    this.rows = [\n      {\n        name: 'Marta Mccoy',\n        salary: 31000,\n        gender: 'M'\n      },\n      {\n        name: 'Fanny Holman',\n        salary: 23000,\n        gender: 'F'\n      },\n      {\n        name: 'Latonya Gibson',\n        salary: 22000,\n        gender: 'F'\n      },\n      {\n        name: 'Ines Wiggins',\n        salary: 35000,\n        gender: 'F'\n      },\n      {\n        name: 'Kathrine Irwin',\n        salary: 38000,\n        gender: 'F'\n      },\n      {\n        name: 'Higgins Oneal',\n        salary: 3500,\n        gender: 'M'\n      },\n      {\n        name: 'Russell Duke',\n        salary: 370000,\n        gender: 'M'\n      },\n      {\n        name: 'Sara Quinn',\n        salary: 23000,\n        gender: 'F'\n      },\n      {\n        name: 'Dona Patterson',\n        salary: 32000,\n        gender: 'F'\n      },\n      {\n        name: 'Clarice Keith',\n        salary: 220,\n        gender: 'F'\n      },\n      {\n        name: 'Petersen Maldonado',\n        salary: 200000,\n        gender: 'M'\n      },\n      {\n        name: 'Tonya Colon',\n        salary: 3800,\n        gender: 'M'\n      },\n      {\n        name: 'Ann Bass',\n        salary: 3000,\n        gender: 'F'\n      },\n      {\n        name: 'Cherie Pickett',\n        salary: 2100,\n        gender: 'F'\n      },\n      {\n        name: 'Holland Mcdonald',\n        salary: 28000,\n        gender: 'M'\n      },\n      {\n        name: 'Casey Dudley',\n        salary: 230,\n        gender: 'F'\n      },\n      {\n        name: 'Sophie Slater',\n        salary: 330,\n        gender: 'F'\n      },\n      {\n        name: 'Rhoda Kent',\n        salary: 3200,\n        gender: 'M'\n      },\n      {\n        name: 'Bennett Sheppard',\n        salary: 3200,\n        gender: 'M'\n      },\n      {\n        name: 'Foreman Hood',\n        salary: 250,\n        gender: 'M'\n      }\n    ];\n  }\n\n  onRowsChanged(rows: Array<any>) {\n    this.summaryRows = {\n      salary: rows.reduce(((total, number) => total + number.salary), 0),\n      gender: 'Male: ' + rows.filter(r => r.gender === 'M').length + ', Female: ' + rows.filter(r => r.gender === 'F').length\n    };\n  }\n\n  onSelectedRowChange(rows) {\n    this.selectedRow = rows;\n  }\n\n}",
