        "ts": "import { Component, OnInit } from '@angular/core';\n\n@Component({\n  selector: 'ugw-table-with-select',\n  templateUrl: './table-with-select.component.html',\n  styleUrls: ['./table-with-select.component.scss']\n})\nexport class TableWithSelectComponent implements OnInit {\n\n  rows: Array<any> = [];\n  columns: Array<any> = [];\n  rowSelected: Array<any> = [];\n\n  constructor() { }\n\n  ngOnInit() {\n    this.initializeColumns();\n    this.initializeRows();\n  }\n\n  initializeColumns() {\n    this.columns = [\n      { name: 'No', prop: 'number' },\n      { name: 'Name', prop: 'name' },\n      { name: 'Age', prop: 'age' },\n      {\n        name: \"Total memorization Al-Qur'an\",\n        prop: 'select',\n        type: 'input-select',\n        options: [\n          { value: '15', label: '15 Juz' },\n          { value: '30', label: '30 Juz' },\n        ]\n      }\n    ];\n  }\n\n  initializeRows() {\n    this.rows = [\n      { number: 1, name: 'Ismail Abdul Jalil Sisha', age: 31, select: '15' },\n      { number: 2, name: 'Fanny Holman', age: 23, select: '30' },\n      { number: 3, name: 'Latonya Gibson', age: 22, select: '15' },\n      { number: 4, name: 'Khalid Khasmiri', age: 28, select: '30' },\n      { number: 5, name: 'Kathrine', age: 18, select: '30' },\n    ];\n  }\n\n\n  onSelectChange(ev) {\n    this.rowSelected = ev;\n  }\n}",
