        "ts": "import { Component, OnInit } from '@angular/core';\n\n@Component({\n  selector: 'ugw-table-with-save-statement',\n  templateUrl: './table-with-save-statement.component.html',\n  styleUrls: ['./table-with-save-statement.component.scss']\n})\nexport class TableWithSaveStatementComponent implements OnInit {\n\n  rows: Array<any> = [];\n  columns: Array<any> = [];\n  selectedRows: Array<any> = [];\n\n  constructor() { }\n\n  ngOnInit() {\n    this.columns = [\n      {\n        name: 'No',\n        prop: 'number'\n      },\n      {\n        name: 'Name',\n        prop: 'name'\n      },\n      {\n        name: 'Salary',\n        prop: 'salary',\n        type: 'input-number',\n        inputType: 'number'\n      },\n      {\n        name: 'Approved',\n        prop: 'approved',\n        type: 'input-checkbox'\n      },\n      {\n        name: 'Status',\n        prop: 'status',\n        type: 'input-select',\n        options: [\n          { label: 'Active', value: 'active' },\n          { label: 'Inactive', value: 'inactive' },\n          { label: 'Pending', value: 'pending' }\n        ]\n      },\n      {\n        name: 'Priority',\n        prop: 'priority',\n        type: 'input-radio'\n      }\n    ];\n\n    this.rows = [\n      { id: 1, number: 1, name: 'Marta Mccoy', salary: 31000, approved: false, status: 'active', priority: 0 },\n      { id: 2, number: 2, name: 'Fanny Holman', salary: 23000, approved: true, status: 'active', priority: 0 },\n      { id: 3, number: 3, name: 'Latonya Gibson', salary: 22000, approved: false, status: 'inactive', priority: 0 },\n      { id: 4, number: 4, name: 'Ines Wiggins', salary: 35000, approved: true, status: 'active', priority: 0 },\n      { id: 5, number: 5, name: 'Kathrine Irwin', salary: 38000, approved: false, status: 'pending', priority: 0 },\n      { id: 6, number: 6, name: 'Higgins Oneal', salary: 3500, approved: true, status: 'active', priority: 0 },\n      { id: 7, number: 7, name: 'Russell Duke', salary: 370000, approved: false, status: 'inactive', priority: 0 },\n      { id: 8, number: 8, name: 'Sara Quinn', salary: 23000, approved: true, status: 'active', priority: 0 },\n      { id: 9, number: 9, name: 'Dona Patterson', salary: 32000, approved: false, status: 'pending', priority: 0 },\n      { id: 10, number: 10, name: 'Clarice Keith', salary: 28000, approved: true, status: 'active', priority: 0 },\n      { id: 11, number: 11, name: 'James Carter', salary: 42000, approved: true, status: 'active', priority: 0 },\n      { id: 12, number: 12, name: 'Patricia Moore', salary: 29000, approved: false, status: 'inactive', priority: 0 },\n      { id: 13, number: 13, name: 'Robert Taylor', salary: 45000, approved: true, status: 'active', priority: 0 },\n      { id: 14, number: 14, name: 'Linda Anderson', salary: 33000, approved: false, status: 'pending', priority: 0 },\n      { id: 15, number: 15, name: 'Michael Thomas', salary: 51000, approved: true, status: 'active', priority: 0 },\n      { id: 16, number: 16, name: 'Barbara Jackson', salary: 27000, approved: false, status: 'inactive', priority: 0 },\n      { id: 17, number: 17, name: 'William White', salary: 39000, approved: true, status: 'active', priority: 0 },\n      { id: 18, number: 18, name: 'Elizabeth Harris', salary: 34000, approved: false, status: 'pending', priority: 0 },\n      { id: 19, number: 19, name: 'David Martin', salary: 48000, approved: true, status: 'active', priority: 0 },\n      { id: 20, number: 20, name: 'Jennifer Thompson', salary: 36000, approved: false, status: 'inactive', priority: 0 }\n    ];\n  }\n\n  onRowSelected($event) {\n    this.selectedRows = $event;\n  }\n\n  onCheckboxChange(_$event: any) {\n  }\n\n  onInputChange(_$event: any) {\n  }\n\n  onSelectChange(_$event: any) {\n  }\n\n  onRadioChange(_$event: any) {\n  }\n\n}",
