        "html": "<div class=\"well well-default\">Selected tab title is {{tabTitle}}</div>\n<uii-tabset>\n  <uiiTabItem title=\"Tab 1\" (selected)=\"onTabItemSelect($event)\">\n    Tab 1 content\n  </uiiTabItem>\n  <uiiTabItem title=\"Tab 2\"  (selected)=\"onTabItemSelect($event)\">\n    Tab 2 content\n  </uiiTabItem>\n  <uiiTabItem title=\"Tab 3\"  (selected)=\"onTabItemSelect($event)\">\n    Tab 3 content\n  </uiiTabItem>\n  <uiiTabItem title=\"Tab 4\"  (selected)=\"onTabItemSelect($event)\">\n    Tab 4 content\n  </uiiTabItem>\n</uii-tabset>",
