        "component": "TabsetDeselectEventComponent",
        "html": "<div class=\"well well-default\">Deselected tab title is {{tabTitle}}</div>\n<uii-tabset>\n  <uiiTabItem title=\"Tab 1\" (deselected)=\"onTabItemDeselect($event)\">\n    Tab 1 content\n  </uiiTabItem>\n  <uiiTabItem title=\"Tab 2\"  (deselected)=\"onTabItemDeselect($event)\">\n    Tab 2 content\n  </uiiTabItem>\n  <uiiTabItem title=\"Tab 3\"  (deselected)=\"onTabItemDeselect($event)\">\n    Tab 3 content\n  </uiiTabItem>\n  <uiiTabItem title=\"Tab 4\"  (deselected)=\"onTabItemDeselect($event)\">\n    Tab 4 content\n  </uiiTabItem>\n</uii-tabset>",
        "ts": "import { Component } from '@angular/core';\n\n@Component({\n  selector: 'ugw-tabset-deselect-event',\n  templateUrl: './tabset-deselect-event.component.html'\n})\nexport class TabsetDeselectEventComponent {\n  tabTitle: string;\n\n  onTabItemDeselect($event) {\n    this.tabTitle = $event.title;\n  }\n\n}",
