        "html": "<button class=\"btn btn-primary\" uiiTooltip=\"Hi! I am tooltip on right\" tooltipPlacement=\"right\">Tooltip on right</button>\n<button class=\"btn btn-primary\" uiiTooltip=\"Hi! I am tooltip on bottom\" tooltipPlacement=\"bottom\">Tooltip on bottom</button>\n<button class=\"btn btn-primary\" uiiTooltip=\"Hi! I am tooltip on left\" tooltipPlacement=\"left\">Tooltip on left</button>\n<button class=\"btn btn-primary\" uiiTooltip=\"Hi! I am tooltip on top\" tooltipPlacement=\"top\">Tooltip on top</button>",
        "ts": "import { Component, OnInit } from '@angular/core';\n\n@Component({\n  selector: 'ugw-placement-tooltip',\n  templateUrl: './placement-tooltip.component.html',\n  styleUrls: ['./placement-tooltip.component.scss']\n})\nexport class PlacementTooltipComponent implements OnInit {\n\n  constructor() { }\n\n  ngOnInit() {\n  }\n\n}",
        "scss": ""
